      if (state === QUOTED) {
        let j = i;
        for (; j < n; j++) {
          const c = chunk[j];
          if (c === '"') break;
          if (c === '\r') {
            line++;
            afterCR = true;
          } else {
            if (c === '\n' && !afterCR) line++;
            afterCR = false;
          }
