        field += chunk.slice(i, j);
        if (j < n) {
          state = QUOTE_SEEN;
          afterCR = false;
          j++;
        }
        i = j;
        continue;
      }

      const c = chunk[i];
      if (c === '\n' && afterCR) {
        // Second half of an outside-quote CRLF; the record was already emitted.
        afterCR = false;
        i++;
        continue;
      }
      afterCR = c === '\r';

