          const d = chunk[j];
          if (d === delimiter || d === '\r' || d === '\n') break;
          j++;
        }
        field += chunk.slice(i, j);
        state = UNQUOTED;
        i = j;
      }
    }
    return records;
  }

  function end() {
    if (ended) return [];
    ended = true;
    if (state === QUOTED) throw new SyntaxError(`Unterminated quoted field at line ${line}`);
    if (state === FIELD_START && row.length === 0) return [];
    row.push(field);
    const last = row;
    row = [];
    field = '';
    return [last];
  }

  return { push, end };
