        field += chunk.slice(i, j);
        if (j < n) {
          state = QUOTE_SEEN;
          afterCR = false;
          j++;
        }
        i = j;
        continue;
      }

      const c = chunk[i];
      if (c === '\n' && afterCR) {
        // Second half of an outside-quote CRLF; the record was already emitted.
        afterCR = false;
        i++;
        continue;
      }
      afterCR = c === '\r';

      if (c === '\r' || c === '\n') {
        line++;
        row.push(field);
        records.push(row);
        row = [];
        field = '';
        state = FIELD_START;
        i++;
      } else if (c === delimiter) {
        row.push(field);
        field = '';
        state = FIELD_START;
        i++;
      } else if (state === QUOTE_SEEN) {
        if (c !== '"') {
