        let j = i + 1;
        while (j < n) {
          const d = chunk[j];
          if (d === delimiter || d === '\r' || d === '\n') break;
          j++;
        }
        field += chunk.slice(i, j);
        state = UNQUOTED;
        i = j;
      }
    }
