'use strict';
const assert = require('node:assert/strict');
const { createParser, parse } = require('./src/csv');

const cases = [
  ['', []],
  ['\uFEFF', []],
  ['\n', [['']]],
  ['\n\n', [[''], ['']]],
  ['a\n', [['a']]],
  ['a\r\nb\rc\n', [['a'], ['b'], ['c']]],
  ['a\r\r\nb', [['a'], [''], ['b']]],
  ['\uFEFFa,b', [['a', 'b']]],
  ['a,\uFEFFb', [['a', '\uFEFFb']]],
  ['ab"c,d"', [['ab"c', 'd"']]],
  ['"a""b","x\r\ny\rz\n"\r\n', [['a"b', 'x\r\ny\rz\n']]],
  ['"",""', [['', '']]],
  ['""""', [['"']]],
  [',', [['', '']]],
  ['"a",\r\n', [['a', '']]],
  ['x\uD83D\uDE00y', [['x\uD83D\uDE00y']]],
];

function splits(text, rows) {
  // single push
  assert.deepEqual(parse(text), rows, JSON.stringify(text));
  // every two-way split and every char-by-char (with empty chunks)
  for (let k = 0; k <= text.length; k++) {
    const p = createParser();
    const out = p.push('').concat(p.push(text.slice(0, k)), p.push(''), p.push(text.slice(k)), p.end());
    assert.deepEqual(out, rows, `${JSON.stringify(text)} @${k}`);
  }
  const p = createParser();
  let out = [];
  for (const ch of text.split('')) out = out.concat(p.push(ch), p.push(''));
  assert.deepEqual(out.concat(p.end()), rows);
}
for (const [t, r] of cases) splits(t, r);

// immediate emission, even before LF of CRLF arrives
{
  const p = createParser();
  assert.deepEqual(p.push('a,b\r'), [['a', 'b']]);
  assert.deepEqual(p.push('\nc'), []);
  assert.deepEqual(p.end(), [['c']]);
  assert.deepEqual(p.end(), []);
  assert.throws(() => p.push(''), Error);
}

// delimiter
assert.deepEqual(parse('a;b,c\n"x;y";z', { delimiter: ';' }), [['a', 'b,c'], ['x;y', 'z']]);
assert.deepEqual(parse('a\tb', { delimiter: '\t' }), [['a', 'b']]);
for (const d of ['', ';;', '"', '\r', '\n', 1, null, '\uD83D\uDE00']) {
  assert.throws(() => createParser({ delimiter: d }), RangeError, String(d));
}
assert.throws(() => createParser().push(1), TypeError);
assert.throws(() => createParser().push(undefined), TypeError);

// line numbers, split at every position
function lineErr(text, n, atEnd) {
  for (let k = 0; k <= text.length; k++) {
    const p = createParser();
    assert.throws(() => { p.push(text.slice(0, k)); p.push(text.slice(k)); p.end(); },
      e => e instanceof SyntaxError && e.message.includes(`line ${n}`) && !/line \d\d/.test(e.message),
      `${JSON.stringify(text)} @${k}`);
  }
}
lineErr('"a" ,b', 1);
lineErr('a\r\n"x\r\ny\rz\n"x', 4);
lineErr('a\n\r\n"b"c', 3);
lineErr('"abc\r\n', 2);
lineErr('a\n"b\n\nc', 4);
{
  const p = createParser();
  assert.throws(() => p.push('x\n"a"\t'), /line 2/);
}

// header mode
assert.deepEqual(parse('', { header: true }), []);
assert.deepEqual(parse('x,x,x_2,x\n1,2,3', { header: true }), [{ x: '1', x_2: '2', x_2_2: '3', x_3: '' }]);
const [obj] = parse('__proto__,b\n1,2', { header: true });
assert.equal(Object.getPrototypeOf(obj), Object.prototype);
assert.deepEqual(Object.keys(obj), ['__proto__', 'b']);
console.log('all checks passed');

